import { createApiClient, createApiHandler, define, effecting, guard, type AppError } from '@gost-kit/common';
import type { AppAction, AppEffect, Dependencies, Paths } from './contracts.js';

// Pre-existing test-only application boundary. Feature implementation must reuse
// this file unchanged; transport/normalization policy is not generated by a skill.
export const createAppEffector = (dependencies: Dependencies, alerts: string[]) => {
  const isAppError = (value: unknown): value is AppError =>
    guard.record(value) && guard.string(value.code) && guard.string(value.message)
    && guard.array(value.path) && value.path.every(guard.string);
  const api = createApiClient<Paths>({
    baseUrl: 'https://api.example.invalid',
    fetch: dependencies.fetch,
    mapErrors: (body) => guard.record(body) && guard.array(body.errors)
      ? body.errors.filter(isAppError) : [],
  });
  const apiHandlers = createApiHandler<Paths, AppAction>(api);
  const appHandlers = define.effector<AppAction, Extract<AppEffect, { type: 'AlertEffect' }>>({
    AlertEffect: async ({ effect }) => { alerts.push(effect.message); },
  });
  return effecting<AppAction, AppEffect, readonly [typeof apiHandlers, typeof appHandlers]>(apiHandlers, appHandlers);
};
